window.SD.stages.push({id:3,icon:'🧭',color:'#7E5BD0',name:'الجذورُ تشتدّ',years:'٨–١٠ سنوات',place:'مانشستر — وقرار الرحيل',
intro:'سنوات القوة الأولى: قيادة في النادي، ثبات أمام السخرية، أول خطبة، أول مشروع صدقة — ثم رسالة الجد التي تقلب البيت، ومجلس الشورى العائلي، والطائرة التي تقلع في عيد ميلاده العاشر. نهاية الفصل البريطاني.',
eps:[
{n:31,t:'قائدُ الفريقِ الصغير',ic:'🥇',age:'٨ سنوات',loc:'نادي السباحة',corner:'sport',goal:'القيادة خدمة وعدل لا تسلّط — أول مسؤولية جماعية',chars:['صلاح الدين','المدرب هاريس','عمر','فريق الصغار'],
scenes:[
{h:'م١ · داخلي — المسبح، إعلان مفاجئ',d:'نهاية التدريب. المدرب هاريس يجمع فريق الصغار عند الحافة ويرفع شارة قماشية حمراء مكتوب عليها Captain.',dlg:[['المدرب هاريس','بطولةُ الأنديةِ بعد شهر… وفريقُ الصغارِ يحتاجُ قائداً. اخترتُ من لم يغبْ حصةً منذ سنتين، ومن يصفُّ أحذيتَكم وأنتم لا ترون… صلاح الدين!'],['صلاح الدين','(يتلقى الشارة مذهولاً — أطفال أكبر منه يتبادلون نظرات) أنا؟ لكن جيمس أسرعُ مني… وأكبر!'],['المدرب هاريس','القيادةُ يا فتى ليست سرعةً في الماء… سنرى إن كنتَ ستفهمُ ما هي.']],vo:'شارةٌ حمراءُ صغيرة… ظننتُها تاجاً، فإذا هي أثقلُ حملٍ حملتُهُ في الثامنة. وأولُ درسٍ في علمٍ سأحتاجُهُ عمري كلَّه: علمِ أن تكونَ مسؤولاً عن غيرِك.'},
{h:'م٢ · داخلي — المسبح، معضلة عمر',d:'أسبوع التحضير. لوحة أزمنة الفريق على الجدار: اسم عمر في القاع بفارق واضح. جيمس يسحب صلاح الدين جانباً.',dlg:[['جيمس','كلنا نعرفُ الحساب: إن أخرجتَ عمرَ من التتابعِ وأدخلتَ بيلي، نكسبُ ثلاثَ ثوانٍ كاملة. أنتَ القائد… قرِّر!'],['صلاح الدين','(ينظر عبر الزجاج إلى عمر الذي يتدرب وحده بعد انصراف الجميع، يعيد المحاولة ويفشل ويعيد)… أمهلْني الليلة.'],['جيمس','القائدُ الذي يتأخرُ في القراراتِ الصعبة… ليس قائداً.'],['صلاح الدين','(يلتفت إليه بهدوء) والقائدُ الذي يرمي جنودَهُ عندَ أولِ صعوبة… ماذا يكون؟']]},
{h:'م٣ · داخلي — البيت، استشارة الليل',d:'صلاح الدين يعرض المعضلة على أبيه فوق رقعة شطرنج مفتوحة بينهما.',dlg:[['أيوب','(يحرك جندي الشطرنج) أخبرني… ماذا كان رسولُ اللهِ ﷺ يفعلُ بالضعيفِ في الصف؟'],['صلاح الدين','قلتَ لي مرة… كان يمشي في السفرِ آخرَ القوم، يُزجي الضعيفَ ويحملُ المتعب.'],['أيوب','أعظمُ قائدٍ في التاريخ… كان يمشي آخرَ القافلة. القائدُ الصغيرُ يسألُ: كيف أكسبُ السباق؟ والقائدُ الحقيقيُّ يسأل: كيف أكسبُ السباقَ بفريقي كلِّه؟ والآن نمْ… وأنا واثقٌ أنكَ ستجدُ الجوابَ الثالث.'],['صلاح الدين','(يرفع رأسه فجأة) الثالث؟… هناك جوابٌ ثالث! (يقفز عن الكرسي) عرفتُه!']],vo:'تلكَ الليلةَ اكتشفتُ أن المعضلاتِ الثنائية — إما الفوزُ وإما الوفاء — يكسرُها دائماً سؤالٌ واحد: وهل جربتَ أن تصنعَ خياراً ثالثاً؟'},
{h:'م٤ · داخلي — المسبح، الخيار الثالث',d:'مونتاج أسبوعين: صلاح الدين يعلن أمام الفريق أن عمر باقٍ في التتابع — وأنه سيتدرب معه شخصياً قبل الحصة بنصف ساعة كل يوم. الفجر: الاثنان وحدهما في الماء، صلاح الدين يصحح وضع ذراع عمر كما علمه المدرب. عمر يتحسن… ثانية، ثم ثانيتين. الفريق يتحول من التذمر إلى التشجيع، وجيمس نفسه ينضم لتدريب الفجر.',dlg:[['عمر','(لاهثاً بعد محاولة ناجحة) لماذا تفعلُ كلَّ هذا لأجلي؟'],['صلاح الدين','لأنكَ أولُ من جلسَ بجانبي يومَ كنتُ وحيداً… ولأن القائدَ لا يقوى بضعفِ جنودِه — يقوى بقوتِهم!']]},
{h:'م٥ · داخلي — مسبح البطولة، يوم السباق',d:'صافرة التتابع. الفريق يتقدم… عمر يسبح مرحلته أفضل سباحة في حياته — لكن الفريق يخسر بفارق ثانية واحدة. وجوه منكسرة عند الحافة. المدرب هاريس يطلب الميكروفون من منظم البطولة.',dlg:[['المدرب هاريس','(أمام الجميع) خسرنا الكأسَ بثانية… لكني أريدُ أن يعرفَ هذا المسبحُ شيئاً: قائدُ فريقِنا رفضَ أن يرميَ أضعفَ سباحيهِ، ودرَّبَهُ بيديهِ حتى صارَ يسبقُ زمنَهُ القديمَ بثانيتين. خسرنا كأساً… وكسبنا قائداً. وأنا أعلمُ أيهما أندر.'],['صلاح الدين','(يرفع عمر معه على منصة الفريق رغم الخسارة، هامساً) العامَ القادم… نكسبُها معاً. كلُّنا.']],vo:'لم أنسَ تصفيقَ الناسِ لفريقٍ خاسر. يومَها فهمتُ جملةَ المدرب: الكؤوسُ تصدأ يا أصدقائي… أما القاعدةُ فتبقى: القائدُ يُكبِرُ من حولَهُ، لا يكبرُ عليهم.'}],
msg:'القائد الحقيقي يمشي آخر القافلة: يقوّي الضعيف ولا يرميه — فالكؤوس تصدأ، وصنيع القائد في رجاله يبقى.',apply:'إن كنت قائداً في لعبة أو مجموعة: ابحث عن أضعف عضو وقوِّه سراً — فهذه أول صفات القائد المسلم.'},

{n:32,t:'ورقةُ الغشِّ الطائرة',ic:'📝',age:'٨ سنوات',loc:'صف الامتحان',corner:'social',goal:'«الله يراني» في الامتحان — من غشنا فليس منا',chars:['صلاح الدين','بيلي','المعلمة كلارك'],
scenes:[
{h:'م١ · داخلي — الصف، صباح الامتحان',d:'صف صامت مرتب صفوفاً متباعدة. امتحان الرياضيات الفصلي — الأصعب. المعلمة توزع الأوراق. صلاح الدين يتنفس ويكتب البسملة في زاوية ورقته الخارجية كعادته.',vo:'كنتُ قد صالحتُ بيلي منذ شهورٍ كما وعدتُ نفسي ليلةَ الحكايةِ الكبرى… صار يجلسُ قربي في الامتحانات. ولم أعرف أن صداقتَنا الصغيرةَ ستدخلُ يومَها أصعبَ امتحاناتِها هي أيضاً — في ورقةِ رياضيات.'},
{h:'م٢ · داخلي — الصف، منتصف الامتحان',d:'السؤال الثامن: مسألة القسمة الطويلة التي يتهيبها الجميع. صلاح الدين عالق. فجأة — حركة من يسار الكادر: بيلي يتظاهر بإسقاط ممحاته، وفي حركة سريعة يدس ورقة صغيرة مطوية تحت حافة طاولة صلاح الدين، ويغمز: خذها. الورقة مفتوحة قليلاً: الحل كاملاً بخط دقيق. المعلمة في آخر الصف لا ترى شيئاً.',dlg:[['بيلي','(هامساً من طرف فمه) حضّرتُها البارحة… القسمةُ كلُّها! خذ — أنا صديقُك!']]},
{h:'م٣ · داخلي — الصف، الصراع الصامت',d:'أطول دقيقة في الحلقة — بلا حوار تقريباً: عينا صلاح الدين على الورقة المطوية… يده اليمنى تزحف نحوها ببطء… لقطة قريبة على سبابته التي تكاد تلمسها — نفس السبابة ترتفع ببطء إلى أعلى (حركته الأزلية). فلاش خاطف: صوت أبيه «الله يراني»، صوت جده عبر الشاشة، درجة الجبل البيضاء. يسحب يده، يقلب الورقة الصغيرة على وجهها دون أن يقرأها، ويعود لمسألته يحلها وحده — يخطئ ويشطب ويعيد، ويترك فرعاً منها فارغاً.',dlg:[['صلاح الدين','(يهمس لنفسه وهو يسلّم ورقته) ناقصةٌ… لكنها كلُّها أنا.']],vo:'قلبتُ الورقةَ ولم أقرأها. ليس لأني لا أريدُ الدرجة… بل لأني أردتُ شيئاً أغلى: أن أبقى أنا. الغشُّ يا أصدقائي لا يسرقُ الإجابةَ فقط… يسرقُكَ أنتَ من نفسِك.'},
{h:'م٤ · داخلي — الصف، بعد النتائج',d:'الأوراق تعاد بعد أيام. صلاح الدين: ٨٧ — وعبارة بخط المعلمة: «الفرع الفارغ أشرف من ألف منقول». مشهد كشف هادئ: المعلمة وجدت ورقة الغش تحت الطاولة أثناء التنظيف وعرفت الخط — تستدعي بيلي وحده بعد الحصة. صلاح الدين ينتظر صديقه في الممر.',dlg:[['بيلي','(يخرج منكس الرأس، درجته صفر وإعادة الامتحان) عرفتْ من الخط… لماذا لم تفضحْني أنتَ وأنت رأيتَ الورقة؟'],['صلاح الدين','لأني صديقُك — والصديقُ يسترُ ويُصلح، لا يفضح. لكن اسمعها مني صريحة: لو أخذتُ ورقتَكَ لكنا سقطنا الاثنان — أنتَ في الامتحان، وأنا في شيءٍ أكبرَ من الامتحان. نبيُّنا ﷺ قال: من غشَّنا فليسَ منا. أنا أريدُكَ منا يا بيلي.'],['بيلي','(صمت طويل… ثم بصوت منكسر) علِّمني القسمةَ الطويلة إذن… بدل الورقة.']]},
{h:'م٥ · داخلي — مكتبة المدرسة، ما بعد الدرس',d:'مشهد ختامي دافئ: الصديقان على طاولة المكتبة، أوراق مسودات بينهما، صلاح الدين يشرح القسمة بطريقة الحلوى المقسومة. بيلي يحل مسألته الأولى صحيحة ويرفع يديه كمن سجل هدفاً.',dlg:[['بيلي','حللتُها! وحدي!'],['صلاح الدين','(يضحك) هذا أحلى من ألفِ ورقةٍ مدسوسة… أليس كذلك؟'],['بيلي','(يفكر ثم يبتسم) درجةٌ ناقصةٌ بشرف… خيرٌ من كاملةٍ بغش. سمعتُكَ تقولُها لنفسِك يومَها — لم أفهمْها إلا الآن.']],vo:'إعادةُ الامتحان: بيلي ٧٤ — بيدِهِ وعقلِه. وأنا تعلمتُ أن أجملَ ردٍّ على من يمدُّ لكَ ورقةَ غش… أن تمدَّ له يدَ تعليم.'}],
msg:'من غشّنا فليس منا: درجةٌ ناقصة بشرف خير من كاملة بغش — والصديق يستر ويُصلح ويُعلّم.',apply:'في أي اختبار قادم ردد قبل الدخول: «درجة ناقصة بشرف خير من كاملة بغش» — ولا تُعِر ولا تستعر إجابة.'},

{n:33,t:'قطرةُ الماءِ العجيبة',ic:'🔬',age:'٨ سنوات',loc:'معرض العلوم المدرسي',corner:'academy',goal:'الإتقان عبادة والعلم آية: «وجعلنا من الماء كل شيء حي»',chars:['صلاح الدين','أيوب','المعلمة كلارك','مدير المدرسة'],
scenes:[
{h:'م١ · داخلي — الصف، إعلان المعرض',d:'المعلمة كلارك تعلن معرض العلوم السنوي: كل تلميذ يختار أعجوبة يشرحها بنموذج. الأطفال يتخاطفون المواضيع: الديناصورات! البراكين! الفضاء! صلاح الدين صامت… يرفع كوب الماء الذي أمامه ويحدق فيه.',dlg:[['المعلمة كلارك','وأنت يا صلاح الدين؟ ماذا اخترت؟'],['صلاح الدين','(يرفع الكوب) هذا. الماء.'],['بيلي','(يضحك الصف) الماء؟! نشربُهُ كلَّ يوم! ما العجيبُ فيه؟'],['صلاح الدين','هذا بالضبطُ سرُّه… أعجبُ الأشياءِ هي التي ننساها لأنها معنا كلَّ يوم.']],vo:'اخترتُ أهونَ شيءٍ في نظرِهم… لأن أبي علمني في لعبةِ «من صنعها؟» أن المعجزاتِ الحقيقيةَ لا تحتاجُ ديناصورات. تحتاجُ عيناً تنتبه.'},
{h:'م٢ · داخلي — البيت، ورشة النموذج',d:'طاولة المطبخ تتحول مختبراً: وعاء زجاجي كبير، مصباح (شمس)، صحن ثلج (سحاب)، وماء ملون. أول تجربة لدورة الماء: البخار لا يتكثف — فشل. الثانية: الغطاء يقع في الماء — فشل. أيوب يراقب من بعيد ولا يتدخل إلا بسؤال.',dlg:[['صلاح الدين','(بعد الفشل السابع، يرمي القلم) يكفي! سأعرضُ رسماً على ورقةٍ مثل الجميع!'],['أيوب','(يقترب ويرفع الغطاء المعوج) تستطيع… لكن أخبرني أولاً: كم مرةً تظنُّ أن الله يدوِّرُ هذه الدورةَ في السماءِ كلَّ يوم… بلا خطأٍ واحد؟ منذ ملايينِ السنين؟'],['صلاح الدين','(يصمت… ينظر للنموذج الفاشل ثم للنافذة الممطرة)… وأنا أستسلمُ في المحاولةِ السابعة؟ (يسحب الكرسي ويجلس) هاتِ الغطاء.'],['أيوب','(يبتسم ويعلق فوق الطاولة ورقة كتبها) وهذه لتسندَك: إنَّ اللهَ يحبُّ إذا عملَ أحدُكم عملاً أن يُتقنَه.']]},
{h:'م٣ · داخلي — المطبخ، ليلة الإتقان',d:'مونتاج المحاولات: ٨… ١٢… ١٧… تعديل زاوية المصباح، تغيير كمية الثلج، إحكام الغطاء. المحاولة العشرون: البخار يصعد… يلامس صحن الثلج… وتتشكل قطرات تنزل «مطراً» داخل الوعاء. صمت… ثم صرخة فرح توقظ يوسف.',dlg:[['صلاح الدين','أمطرتْ! يا بابا يا ماما أمطرتْ في مطبخِنا! (يسجد سجدة شكر سريعة عفوية بجانب الطاولة)'],['مريم','(تحمل شام وتضحك) أول عالمٍ يسجدُ شكراً في هذا المطبخ… سجِّلِ الرقمَ يا أيوب: عشرون محاولة.'],['صلاح الدين','(يكتب على النموذج بخط عريض) صُنعَ في عشرين محاولة — والحمدُ لله.']],vo:'عشرون محاولةً لأصنعَ مطرةً صغيرةً في وعاء… فكم من كمالٍ في المطرةِ الحقيقية؟ كلما أتقنتُ شيئاً صغيراً… ازددتُ ذهولاً من إتقانِ خالقي للكونِ كلِّه. الإتقانُ يا أصدقائي بابٌ من أبوابِ معرفةِ الله.'},
{h:'م٤ · داخلي — قاعة المعرض، يوم العرض',d:'طاولات المعرض: براكين تثور بالخل، ومجسمات كواكب. طاولة صلاح الدين الأبسط شكلاً — لكن أمامها أطول طابور: دورة ماء تعمل حية، وبجانبها لوحة كتب عليها بخطه العربي الجميل وتحتها الترجمة: ﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾ — "We made from water every living thing". مدير المدرسة يقف أمامها طويلاً.',dlg:[['المدير','من علَّمكَ هذه الجملة؟'],['صلاح الدين','هي من كتابِنا — القرآن. نزلتْ قبلَ ألفٍ وأربعمئةِ سنة… والعلماءُ اليومَ يقولون: كلُّ حيٍّ من الماء. كتابُنا سبقَ المجاهر!'],['المدير','(يتأملها ثم يلتفت للمعلمة كلارك) أريدُ هذه اللوحةَ والنموذجَ في مدخلِ المدرسة… ليقرأها كلُّ من يدخل.']]},
{h:'م٥ · داخلي — مدخل المدرسة، بعد أيام',d:'لقطة ختامية: النموذج في خزانة زجاجية عند المدخل، الآية بالعربية والإنجليزية تلمع تحت الإضاءة، وأطفال يتوقفون أمامها كل صباح. صلاح الدين يمر بحقيبته ويبتسم.',vo:'ظلَّ نموذجي في مدخلِ المدرسةِ سنتين… يقرأُ آيةَ ربي كلُّ داخلٍ وخارج. يومَها فهمتُ معادلةً سأبني عليها عمري: حينَ تتقنُ عملَك… يصيرُ عملُكَ منبرَك. أتقنْ، يتكلمْ عنكَ وعن دينِكَ ما صنعتْ يداك.'}],
msg:'إن الله يحب إذا عمل أحدكم عملاً أن يتقنه: أتقن صنعتك يصبح عملُك منبراً يتكلم عن دينك.',apply:'أياً كان واجبك القادم (رسم، بحث، مشروع): أعد تحسينه ٣ مرات قبل تسليمه بنية «الله يحب المتقن».'},

{n:34,t:'صائمٌ بين الحصص',ic:'🌙',age:'٨ سنوات',loc:'المدرسة — رمضان',corner:'ibada',goal:'أول رمضان كامل: صيام يوم مدرسي كامل بعزيمة وفرح',chars:['صلاح الدين','مريم','أيوب','المعلمة كلارك','عمر','توم'],
scenes:[
{h:'م١ · داخلي — المطبخ، سحور النية الكبيرة',d:'الثالثة والنصف فجراً. سحور هادئ على ضوء خافت. صلاح الدين (٨ سنوات) يأكل بجدية غير مسبوقة — اليوم ليس تدريباً.',dlg:[['صلاح الدين','اليومَ أصومُهُ كاملاً — حتى المغرب. مدرسةً ورياضةً وكلَّ شيء. مثلُكم تماماً.'],['مريم','متأكد يا حبيبي؟ يومُ المدرسةِ طويل… ولا حرجَ أن تفطرَ إن تعبتَ، فأنتَ بعدُ غيرُ مكلف.'],['صلاح الدين','(يشرب الماء حتى آخر قطرة قبيل الأذان) أطفالُ الصحابةِ صاموا وهم يُلَهَّون باللعبِ من الصوف… وأنا عندي أفضلُ من اللعب: عندي نية! اللهم إني نويتُ صيامَ يومٍ كامل.'],['أيوب','(يربت كتفه) إذن نراكَ على مائدةِ الإفطار… يا صائم.']],vo:'ثمانيةُ أعوامٍ وأولُ يومٍ كامل. لم يفرضْهُ عليَّ أحد — وهنا كان سرُّ حلاوتِه: الجوعُ الذي تختارُهُ أنت… يشبعُكَ من الداخل.'},
{h:'م٢ · داخلي — المدرسة، عرض المعلمة الرحيم',d:'استراحة الغداء. صلاح الدين يجلس بلا صندوق طعام لأول مرة. المعلمة كلارك تقترب بقلق حقيقي.',dlg:[['المعلمة كلارك','صلاح الدين… أخبرتْني أمُّكَ أنه شهرُ رمضان. اسمع: أنتَ صغير، ولو أردتَ أن تأكلَ فلن يعرفَ أحد — يمكنُكَ الجلوسُ في مكتبي بعيداً عن الأنظار.'],['صلاح الدين','(يبتسم بامتنان) شكراً من قلبي… لكن سيعرفُ واحد: الذي أصومُ له! الصيامُ يا معلمتي ليس عن الطعامِ فقط — إنه هديتي لربي، وأنا لا أسحبُ هداياي. ثم إني ألعبُ لعبةً ممتعة: كلما جعتُ تذكرتُ الأطفالَ الذين يجوعون بلا اختيار… فأدعو لهم وأكملُ بفرح.'],['المعلمة كلارك','(تصمت متأثرة)… ثمانيةُ أعوامٍ وتقولُ هذا الكلام. حسناً يا سيد صلاح الدين — لكن مكتبي مفتوحٌ إن احتجتَ راحة… لا طعاماً.']]},
{h:'م٣ · خارجي — حصة الرياضة، امتحان العطش',d:'ملعب المدرسة، شمس نادرة في مانشستر. جري وكرة. صلاح الدين يلعب بكامل جهده — ثم لحظة الحقيقة: طابور صنابير المياه بعد الجري، الأطفال يشربون بصوت مسموع. يقف في الطابور بالعادة… ثم يتذكر ويخرج منه، يبلل وجهه فقط ويجلس تحت الشجرة.',dlg:[['عمر','(صائم مثله، يجلس بجانبه بشفتين جافتين) أصعبُ لحظة… صوتُ الماء.'],['صلاح الدين','(يضحك بجفاف) تخيلْ معي: الآن في الجنةِ بابٌ اسمُهُ الريان… لا يدخلُهُ إلا الصائمون. أبي يقول: من ظمئ له في الدنيا… رويَ منه هناك ريّاً لا ظمأَ بعدَه.'],['عمر','(يغمض عينيه) الريان… حسناً، يستحقُّ العطش. لكن لا تذكرِ العصيرَ حتى المغرب!']]},
{h:'م٤ · داخلي — الصف، مشهد المثلجات',d:'الحصة الأخيرة: مفاجأة نهاية الفصل — المعلمة توزع مثلجات على الصف احتفالاً. الأطفال يهللون. تصل إلى صلاح الدين وتتوقف محرجة… فيمد يده ويأخذ اثنتين.',dlg:[['المعلمة كلارك','(مندهشة) لكنك…!'],['صلاح الدين','صائم! هذه لتوم لأن مثلجتَهُ سقطت الأسبوعَ الماضي… وهذه أضعُها في ثلاجةِ المطبخِ إن سمحتِ — موعدي معها بعد ثلاثِ ساعاتٍ وسبعِ دقائق!'],['توم','(يستلم المثلجة مذهولاً ويهمس لبيلي) صائمٌ… ويوزعُ المثلجات؟! أصدقاؤنا هؤلاء ليسوا أشخاصاً عاديين.']],vo:'قالها توم مازحاً… لكنها وصفتِ الصيامَ كلَّه: أن تملكَ الشيءَ وتؤجلَهُ بابتسامة — هذه القوةُ التي لا يفهمُها إلا من ذاقَها.'},
{h:'م٥ · داخلي — البيت، لحظة المغرب',d:'الدقائق الأخيرة: صلاح الدين واقف عند النافذة يراقب السماء، المائدة خلفه جاهزة، مثلجة المدرسة في كأس بجانب التمر. صوت أذان المسجل يرتفع… العائلة كلها تنظر إليه هو.',dlg:[['أيوب','(يقدم له التمرة بيده) تفضل يا بطل… أنتَ أولُ من يفطرُ اليوم.'],['صلاح الدين','(يقول الدعاء بتأنٍ) ذهبَ الظمأُ وابتلَّتِ العروقُ وثبتَ الأجرُ إن شاء الله. (يأكل التمرة ويغمض عينيه طويلاً)… الآن فهمتُ لماذا تبتسمون هكذا كلَّ مغرب! للصائمِ فرحتان — وهذه الأولى!'],['الجد (عبر الهاتف مكبراً)','اللهُ أكبر! صامَ حفيدي يومَهُ الأول! يا صلاحَ الدين: أولُ يومٍ لا يُنسى أبداً… سترويهِ لأحفادِكَ يوماً — صدِّقني، أنا ما زلتُ أذكرُ يومي الأولَ قربَ القدس!']],vo:'وصدقَ جدي… ها أنا أرويهِ لكم. يا أطفالَ الأمة: يومُكم الأولُ الكاملُ قادم — اجعلوهُ حكايةً تستحقُّ أن تُروى.'}],
msg:'الصيام هديتك لربك: جوعٌ تختاره يشبعك من الداخل — وللصائم فرحتان وباب الريان ينتظر.',apply:'صم يوماً تطوعاً (اثنين أو خميس) في يوم عادي لك فيه نشاط — واكتشف قوة إرادتك الحقيقية.'},

{n:35,t:'ميداليةُ نصفِ الجبل',ic:'🏅',age:'٨ سنوات ونصف',loc:'مسجد النور',corner:'quran',goal:'إتمام نصف جزء عم ومسابقة المسجد — الحفظ مع الفهم لا الببغاوية',chars:['صلاح الدين','مريم','الشيخ إدريس','أطفال المسابقة'],
scenes:[
{h:'م١ · داخلي — البيت، ليلة المراجعة',d:'لوحة الجبل على الجدار: نصفها ملون — ١٩ سورة. غداً مسابقة مسجد النور السنوية. مريم تراجع معه بطريقتها الخاصة: لكل سورة قصتها قبل تسميعها.',dlg:[['مريم','قبل أن تسمِّعَ الفيل… احكِ لي: ماذا حدث؟'],['صلاح الدين','أبرهةُ جاءَ بجيشٍ وفيلٍ ضخمٍ ليهدمَ الكعبة! والناسُ لا يقدرون عليه… فأرسلَ اللهُ طيراً صغيرةً بحجارةٍ من نار، فصارَ الجيشُ كأوراقِ الشجرِ الممضوغة! الدرس: بيتُ اللهِ يحميهِ الله… والقويُّ الحقيقيُّ ليس صاحبَ الفيل!'],['مريم','(تبتسم) الآن سمِّعْها… سترى كيف تخرجُ الحروفُ حيةً حين تعرفُ حكايتَها.']],vo:'كان بعضُ أصحابي يحفظون أسرعَ مني — يبتلعون السورَ ابتلاعاً. أما أمي فكانت تطبخُ الحفظَ على نارٍ هادئة: قصةٌ، ثم معنى، ثم حروف. وغداً… سيظهرُ الفرق.'},
{h:'م٢ · داخلي — مسجد النور، أجواء المسابقة',d:'المسجد مزين، منبر صغير للأطفال، لجنة من ثلاثة بينهم الشيخ إدريس، والأهالي صفوف. أطفال يتنافسون: بعضهم يسمّع كالسهم المنطلق — سرعة مذهلة. طفل يحفظ جزء عم كاملاً يتصدر لوحة النقاط. صلاح الدين يسمّع سوره التسع عشرة بترتيل هادئ متأنٍ.',dlg:[['طفل منافس','(هامساً بفخر لصلاح الدين) أنا أحفظُ ضعفَك! سمعتَ سرعتي؟'],['صلاح الدين','(بلا ضيق) ما شاء الله عليك… ادعُ لي أن ألحقَك!']]},
{h:'م٣ · داخلي — المسجد، سؤال المعاني المفاجئ',d:'الشيخ إدريس يرفع يده موقفاً إعلان النتائج: «قبل الختام… فقرة لم تكن في البرنامج». يستدعي المتصدرين الثلاثة وصلاح الدين.',dlg:[['الشيخ إدريس','سؤالٌ واحدٌ لكلٍّ منكم — ليس حفظاً: لماذا أهلكَ اللهُ أصحابَ الفيل؟ (المتسابق الأول يصمت ويحمرّ… الثاني يقول: لأنهم أشرار؟) وأنتَ يا صلاح الدين — قل لنا: ما قصةُ قريشٍ التي بعدَها؟ ولماذا جاءتِ السورتان جارتين؟'],['صلاح الدين','(يقف باطمئنان من عرف ما يقول) اللهُ أهلكَ الفيلَ ليحميَ بيتَهُ… وليحفظَ الأمنَ لقريش! ولهذا جاءت «لإيلافِ قريش» بعدَها مباشرة: يذكِّرُهم اللهُ — أطعمكم من جوعٍ وآمنكم من خوف… فاعبدوا ربَّ هذا البيت! النعمتان الكبيرتان في الدنيا كلِّها: الطعامُ والأمان. جدّتي تقولُها في دعائها كلَّ جمعة!'],['الشيخ إدريس','(يلتفت للجنة والمسجد صامت)… سمعتم؟ حفظٌ يمشي على قدمين!']],vo:'لم أكن أعلمُ أن اللجنةَ قررتْ تلك الليلةَ تغييرَ نظامِ المسابقةِ للأبد: من عامِها صار للفهمِ درجاتٌ كدرجاتِ الحفظ. أمي سبقتْ زمانَها… بقصصِ ما قبلَ التسميع.'},
{h:'م٤ · داخلي — المسجد، جائزة تُستحدث',d:'إعلان النتائج: المركز الأول في الحفظ لصاحب الجزء الكامل — تصفيق مستحق. ثم يقف الشيخ إدريس ويخرج من جيبه ميدالية إضافية لم تكن معدة.',dlg:[['الشيخ إدريس','وجائزةٌ نعلنُها أولَ مرةٍ هذا العام — وستبقى بعدَنا: ميداليةُ «حافظٌ يفهم». لمن رتَّلَ فأسمعَنا المعنى قبل الحرف… صلاحُ الدين! (تصفيق) يا أحبابي: القرآنُ ما نزلَ ليُسابَقَ به… نزلَ ليُفهَمَ ويُعاشَ به. احفظوا قليلاً وافهموا كثيراً… خيرٌ من أن تحفظوا كثيراً ولا تحملوا منه شيئاً.'],['صلاح الدين','(يتسلم الميدالية ويبحث بعينيه عن أمه في قسم النساء… يرفعها نحوها) هذه لصاحبةِ القصص!']]},
{h:'م٥ · داخلي — البيت، تعليق الميدالية',d:'الميدالية تعلق على لوحة الجبل — عند منتصفه بالضبط. مريم تكتب تحتها: «النصف الأول: بالفهم».',dlg:[['مريم','نصفُ الجبل يا صلاح الدين… والنصفُ الثاني؟'],['صلاح الدين','بالفهمِ أيضاً! لكن يا ماما… (يتردد) الطفلُ الفائزُ يحفظُ الجزءَ كلَّه. متى ألحقُه؟'],['مريم','(تمسك وجهه بيديها) يا حبيبي… أنتَ لا تسابقُهُ هو. أنتَ تسابقُ صلاحَ الدين الذي كان بالأمس. سابقْ نفسَك… واترك الباقي لله.']],vo:'سابقْ نفسَك… القاعدةُ نفسُها من المسبحِ إلى المصحف. وبعدَ سنواتٍ حينَ أُجيزَ بالقرآنِ كاملاً، سُئلتُ عن سرّي فقلت: أمي… كانت تحكي لي السورةَ قبل أن أحفظَها. هذا كلُّ السر.'}],
msg:'القرآن نزل ليُفهم ويُعاش لا ليُسابَق به: احفظ قليلاً وافهم كثيراً — وحكاية السورة قبل حفظها هي كل السر.',apply:'راجع آخر سورة حفظتها: هل تعرف قصتها ومعناها؟ اسأل أو ابحث ثم احكِ معناها لأحد أفراد بيتك.'},

{n:36,t:'ساحةُ السخرية',ic:'🛡️',age:'٩ سنوات',loc:'ساحة المدرسة',corner:'fortress',goal:'الثبات أمام الاستهزاء: العزة بلا عدوان، والحلم قوة لا ضعف',chars:['صلاح الدين','داني (طالب أكبر)','عمر','المعلمة كلارك','أيوب'],
scenes:[
{h:'م١ · داخلي — غرفة المصادر، وقت الظهر',d:'زاوية هادئة خصصتها المدرسة: صلاح الدين وعمر يصليان الظهر. من الباب الزجاجي يراقبهما داني — طالب في الحادية عشرة، ضخم، حوله ثلاثة أتباع يضحكون كلما ضحك.',vo:'في كلِّ مدرسةٍ ساحة… وفي كلِّ ساحةٍ واحدٌ مثلُ داني: صوتُهُ أعلى من الجميع، وقلبُهُ — كما ستكتشفون — أصغرُ مما يبدو.'},
{h:'م٢ · خارجي — الساحة، مشهد السخرية',d:'الاستراحة. داني يعترض طريق صلاح الدين أمام جمهور صغير، يقلد حركة السجود بطريقة مضحكة مبالغ فيها.',dlg:[['داني','انظروا! هكذا يفعلُ في الغرفة! (ينقر برأسه الأرض) كالدجاجةِ التي تلتقطُ الحب! دجاجة! دجاجة! (الأتباع يقهقهون)'],['صلاح الدين','(الدم يصعد إلى وجهه، قبضته تنقبض ببطء — لقطة قريبة على القبضة… ثم فلاش صوتي: «ليسَ الشديدُ بالصُّرعة». القبضة تنفتح. يرفع رأسه وينظر في عيني داني مباشرة، بصوت هادئ يسمعه الجميع) أنا لا أنقرُ الأرض يا داني… أنا أسجدُ للذي خلقَك. أعلى لحظاتي… حين أكونُ أقربَ ما يكونُ إلى ربي. جرِّبْ أن تعرفَ قبلَ أن تضحك.'],['داني','(يفتح فمه ولا يجد شيئاً — توقع بكاءً أو لكمة، فوجد جبلاً) …دجاجةٌ تتفلسف! (يضحك وحده هذه المرة… الأتباع صامتون)']],vo:'اكتشفتُ يومَها سلاحَ الأنبياء: الكلمةُ الهادئةُ في وجهِ الصاخب… تكسرُهُ أكثرَ من مئةِ لكمة. الغاضبُ يعطي خصمَهُ ما يريد — والثابتُ يحيِّرُه.'},
{h:'م٣ · داخلي — البيت، التصعيد الصحيح',d:'المضايقات تتكرر أسبوعاً: دفعة في الطابور، حقيبة تُرمى. صلاح الدين يجلس مع أبيه — متعب لكن غير منكسر.',dlg:[['صلاح الدين','صبرتُ ولم أردَّ… لكنه يزداد. هل أظلُّ أصبر؟ أم… أضربُه؟ أنا أقوى مما يظن — تدريبُ السباحةِ ليس مزاحاً!'],['أيوب','(يبتسم لثقته ثم يجدّ) لا هذا ولا ذاك. اسمع الفرقَ الدقيق: الحِلمُ أن تملكَ الردَّ وتتركَهُ ترفعاً — وهذا ما فعلتَ، وأحسنت. أما السكوتُ على أذىً يتكرر فليس حلماً… اسمُهُ تمكينُ الظالم. النبيُّ ﷺ عفا عمن أساءَ إليه هو، لكنه ما سكتَ عن ظلمٍ يمسُّ الحق. غداً تخبرُ معلمتَك — وهذا ليس وشاية…'],['صلاح الدين','(مقاطعاً بتردد) في المدرسةِ يسمّونها وشاية!'],['أيوب','الوشايةُ أن تفضحَ لتؤذي. أما أن تبلِّغَ لتوقفَ أذىً عنكَ وعمن سيأتي بعدَك… فهذا اسمُهُ حمايةُ الحق. والفرقُ بينهما: النية.']]},
{h:'م٤ · داخلي — مكتب المعلمة، ثم الساحة',d:'صلاح الدين يبلّغ المعلمة كلارك بهدوء ودقة — بلا مبالغة ولا دموع. المدرسة تتحرك: جلسة لداني مع المرشد، ومكالمة لأهله. مشهد لاحق في الساحة: داني يقترب من صلاح الدين وحده — بلا أتباع — متردداً لأول مرة.',dlg:[['داني','(يحك رأسه) اسمع… المرشدُ قال إن أبي سيأتي غداً. أنا… (يبلع الكلمة) لماذا لم تشتمْني ولو مرة؟ الجميعُ يشتمُني حين أغيظُهم. أنتَ فقط… تقفُ هكذا. كالسور.'],['صلاح الدين','لأني لستُ غاضباً منك يا داني… أنا فقط لا أسمحُ لك. وهناك فرق. (يمد يده فجأة) تعالَ جرِّبْ شيئاً أفضلَ من جمهورِ الضحك: عندنا مباراةٌ ناقصُها لاعبٌ ضخمٌ مثلُك.'],['داني','(ينظر لليد الممدودة مذهولاً… ثم يصافح) …أنتم المسلمون غريبون. أسخرُ منكَ أسبوعاً فتدعوني للعب؟!'],['صلاح الدين','(يضحك) نبيُّنا علَّمَنا: ادفعْ بالتي هي أحسن… فإذا الذي بينكَ وبينهُ عداوةٌ كأنه وليٌّ حميم. تعالَ والعب — وسترى كيف يصيرُ العدوُّ صديقاً.']]},
{h:'م٥ · خارجي — الساحة، بعد أسابيع',d:'لقطة ختامية دالة: استراحة عادية — داني يلعب في فريق صلاح الدين، ويصدّ بجسده الضخم طفلاً حاول دفع عمر مازحاً بخشونة: «مهلاً! هذا صديقي». صلاح الدين وعمر يتبادلان نظرة ضاحكة. وعند باب غرفة المصادر وقت الظهر… داني واقف يحرس الباب من الإزعاج بذراعين مكتوفتين، كحارس قلعة.',dlg:[['عمر','(هامساً وهما يدخلان للصلاة) الدجاجة… صارَ عندها ديكُ حراسة!'],['صلاح الدين','(يضحك ثم يجدّ) ليس ديكاً يا عمر… إنسانٌ وجدَ أخيراً من يراهُ بلا خوف. الساخرون يا صديقي… أكثرُهم جوعى إلى صديقٍ واحدٍ حقيقي.']],vo:'ادفعْ بالتي هي أحسن… جرَّبتُها في التاسعةِ فإذا هي تعملُ كالسحر — وما زلتُ أجرِّبُها إلى اليوم، على أسوارِ مدارسَ وساحاتِ أممٍ أكبر. الآيةُ نفسُها… والنتيجةُ نفسُها.'}],
msg:'ادفع بالتي هي أحسن فإذا عدوُّك وليٌّ حميم: قف كالسور بلا كسرٍ ولا عدوان — وبلّغ عن الأذى فهذه حماية لا وشاية.',apply:'إن سخر أحد من دينك أو شكلك: لا تضرب ولا تنكسر — قف مستقيماً وأجب بجملة عزيزة هادئة، وأخبر من يحميك.'},

{n:37,t:'الفتى القادمُ من غزة',ic:'🕊️',age:'٩ سنوات',loc:'صف المدرسة',corner:'quds',goal:'القضية تتجسد في صديق: من التعاطف إلى النصرة العملية',chars:['صلاح الدين','أنس','المعلمة كلارك','عمر'],
scenes:[
{h:'م١ · داخلي — الصف، صباح غير عادي',d:'المعلمة كلارك تدخل ومعها طفل نحيل بعينين واسعتين شاردتين، يحمل حقيبة شبه فارغة. يقف عند السبورة ينظر إلى الأرض.',dlg:[['المعلمة كلارك','أحبائي… هذا أنس، زميلُكم الجديد. جاءَ من مكانٍ بعيدٍ اسمُهُ غزة، وهو يتعلمُ الإنجليزيةَ الآن. من يتطوعُ ليكونَ رفيقَهُ الأول؟'],['صلاح الدين','(يده ترتفع قبل أن يكتمل السؤال — يكاد يقف) أنا! أنا أتكلمُ العربية! (يلتفت لأنس ويقول بالعربية) أهلاً أنس! تعالَ اجلسْ بجانبي — أنا صلاحُ الدين!'],['أنس','(يرفع عينيه لأول مرة عند سماع العربية… ونصف ابتسامة تولد)']],vo:'غزة… كنتُ أسمعُها في دعاءِ القنوتِ وأراها في صندوقِ تبرعاتِ المسجد. وفي ذلك الصباح… دخلتْ غزةُ صفَّنا على قدمين صغيرتين، وجلستْ بجانبي.'},
{h:'م٢ · داخلي/خارجي — مونتاج الترويض اللطيف',d:'أسابيع متتابعة: صلاح الدين يترجم لأنس دروس المعلمة همساً. يقسم سندويشه نصفين كل يوم — بلا سؤال. يدخله فريق كرة الاستراحة: أنس يراوغ ببراعة مدهشة فيصفق له الجميع — أول ضحكة كاملة له. عمر يعلمه أسماء اللاعبين بالإنجليزية. لكن في لحظات الهدوء… يشرد أنس فجأة، وعيناه تسافران بعيداً.',dlg:[['عمر','(هامساً لصلاح الدين والكرة بينهما) لاحظتَ؟ يضحكُ معنا… ثم يطفأُ فجأةً كأن أحداً أطفأَ النور.'],['صلاح الدين','(يراقب أنس الشارد) لأن نصفَهُ هنا يا عمر… ونصفَهُ الآخرَ ما زالَ هناك.']]},
{h:'م٣ · داخلي — بيت صلاح الدين، ليلة الحكاية',d:'أول دعوة عشاء. بعد الأكل، على سجادة غرفة صلاح الدين، بين مجسمات وكتب — يفتح أنس قلبه لأول مرة، بهدوء من اعتاد ألا يبكي أمام أحد.',dlg:[['أنس','بيتُنا كان قربَ البحر… أسمعُ الموجَ من نافذتي مثلما تسمعُ أنتَ المطر. كان لي مكتبٌ أصفرُ مثلُ مكتبِكَ هذا… وجدّتي في الطابقِ الأول، تخبزُ كلَّ جمعة.'],['صلاح الدين','(بصوت خفيض) وأين هم الآن؟'],['أنس','جدّتي رفضتِ الخروج. قالت: البيوتُ إذا تركَها أهلُها كلُّهم… ماتت. بقيتْ لتبقيَهُ حياً. (يخرج من جيبه حجراً صغيراً أملسَ) هذا من شاطئنا… كلُّ ما حملتُه. أمسكُهُ فأسمعُ الموج.'],['صلاح الدين','(يتناول الحجر بيدين مرتجفتين كمن يحمل شيئاً مقدساً… ثم يقوم فجأة إلى جداره، ينزع رسمة القبة الذهبية القديمة ويعلق مكانها ورقة جديدة، ويعيد القبة بجانبها) من الليلة… القدسُ وغزةُ جارتان على جداري، كما نحن جاران في الصف.']],vo:'تلكَ الليلةَ لم أنم. كنتُ أعرفُ القضيةَ من الصورِ والخطب… أما الآن فصارَ لها صوتُ موجٍ في حجر، وجدّةٌ تحرسُ بيتاً، ومكتبٌ أصفرُ مثلُ مكتبي. القضايا الكبرى يا أصدقائي لا تدخلُ القلبَ خريطةً… تدخلُهُ وجهَ صديق.'},
{h:'م٤ · داخلي — الصف، أنس يحكي للجميع',d:'بعد شهرين — إنجليزية أنس تحسنت. المعلمة كلارك تخصص حصة «من أين جئنا»: كل طفل يحكي عن جذوره. يصل الدور لأنس — يتردد وينظر لصلاح الدين، فيومئ له بثقة: احكِ.',dlg:[['أنس','(واقفاً، بإنجليزية متأنية) جئتُ من غزة… على بحرٍ أزرقَ جميل. الناسُ هناك يحبون الحياةَ مثلكم: يلعبون الكرةَ على الشاطئ، ويحفظون القرآن، وأعراسُهم أصوانُها عالية! لكنهم لا يستطيعون السفر… ولا يأتيهم دواءٌ كافٍ ولا كهرباءُ الليلِ كلِّه. أنا لا أريدُكم أن تحزنوا… أريدُكم فقط أن تعرفوا: نحن أطفالٌ مثلُكم تماماً… فقط نحتاجُ أن يفتحَ أحدُهم البابَ.'],['الصف','(صمت بليغ… ثم تصفيق حار طويل، والمعلمة تمسح عينيها)']]},
{h:'م٥ · داخلي — غرفة صلاح الدين، ليلاً',d:'لقطة ختامية: الجدار وقد اكتملت خريطته الصغيرة — رسمة القبة، وبجانبها رسمة جديدة: بحر وبيوت صغيرة وكتب تحتها «غزة — بيت أنس وجدته»، وبينهما شريط لاصق أحمر يصلهما. صلاح الدين يضع حجر أنس (أهداه إياه) على رف كنوزه بين الميداليات.',dlg:[['صلاح الدين','(يهمس وهو يطفئ النور) اللهم احفظْ جدةَ أنس والبيتَ الذي تحرسُه… واجعلني ممن يفتحون الباب.']],vo:'حجرٌ صغيرٌ فيه صوتُ موج… ما زالَ معي إلى اليوم. حملتُهُ في جيبي يومَ حطتْ طائرتُنا في عمّان، ويومَ رأيتُ فلسطينَ من الجبل، ويومَ… لكن مهلاً — لكلِّ حكايةٍ وقتُها. المهم: القضيةُ صارَ لها في قلبي عينان.'}],
msg:'القضايا الكبرى لا تدخل القلب خريطةً بل وجهَ صديق: افتح قلبك للقادم الغريب — فنصرته تبدأ بمقعد بجانبك.',apply:'ابحث في محيطك عن «الجديد» أو «الوحيد» — في الصف أو الجيران — وكن أنت أول من يمد له اليد هذا الأسبوع.'},

{n:38,t:'دقيقتانِ على المنبر',ic:'🎤',age:'٩ سنوات',loc:'مسجد النور — برنامج الناشئة',corner:'academy',goal:'أول خطبة: فن الكلمة مسؤولية — قل خيراً أو اصمت، وإذا قلت فأتقن',chars:['صلاح الدين','الشيخ إدريس','أيوب','يوسف','شام'],
scenes:[
{h:'م١ · داخلي — مسجد النور، بعد عصر السبت',d:'الشيخ إدريس يعلن أمام حلقة الناشئة عن منبر صغير خشبي جديد وضع بجانب المنبر الكبير.',dlg:[['الشيخ إدريس','هذا «منبرُ الناشئة»! كلَّ سبتٍ يقفُ عليه واحدٌ منكم دقيقتين: كلمةٌ عن خلقٍ أو قصة. من يفتتحُهُ الأسبوعَ القادم؟'],['صلاح الدين','(يده ترتفع بحماس قبل عقله) أنا!'],['الشيخ إدريس','اللهُ أكبر! سجلناها: صلاحُ الدين — عن ماذا ستتكلم؟'],['صلاح الدين','عن… عن… (أول لحظة تفكير حقيقية) الصدق!']],vo:'رفعتُ يدي في ثانيةِ حماس… وقضيتُ الليلَ كلَّهُ أندم! دقيقتان أمامَ المسجدِ الملآن؟ أنا الذي يرتجفُ صوتي في طابورِ الصباح؟ لكنَّ الكلمةَ خرجتْ… ووعدُ الرجالِ دَين.'},
{h:'م٢ · داخلي — البيت، مطبخ الخطبة',d:'طاولة المكتب: أوراق مسودة كثيرة مشطوبة. صلاح الدين يكتب خطبته الأولى — كلها آيات وأحاديث منقولة محفوظة. يعرضها على أبيه.',dlg:[['أيوب','(يقرأ ويهز رأسه) جميلة… وميتة.'],['صلاح الدين','ميتة؟!'],['أيوب','كلامٌ صحيحٌ كلُّه — لكن أيَّ سطرٍ منها عشتَهُ أنت؟ اسمع قاعدةَ الخطباءِ الأولى: احكِ ما عشتَ… لا ما قرأتَ فقط. الناسُ تنسى المواعظَ وتحفظُ الحكايات. عندكَ عن الصدقِ حكايةٌ يعرفُها هذا البيتُ جيداً… (يبتسم ويشير نحو رف المزهرية الجديدة)'],['صلاح الدين','(يتسع فمه) المزهرية؟! أحكيها أمامَ المسجد؟! سيضحكون عليّ!'],['أيوب','سيضحكون معك… ثم يبكون معك. وهذا هو الفرقُ بين خطبةٍ تُسمَعُ وخطبةٍ تُحفَظ.']]},
{h:'م٣ · داخلي — غرفة الجلوس، بروفة البيت',d:'مشهد كوميدي حنون: صلاح الدين واقف على كرسي (منبر مؤقت)، جمهوره: أيوب ومريم، ويوسف (٥ سنوات) يقاطع بأسئلة، وشام الرضيعة تصفق عشوائياً وتصرخ فرحاً في أهم اللحظات.',dlg:[['صلاح الدين','(يخطب بجدية) …فلما كسرتُ المزهريةَ فكرتُ أن أخبئَ الأمرَ لكن—'],['يوسف','(مقاطعاً بذعر) أنتَ الذي كسرَ مزهريةَ ماما؟!! سأخبرُ تيتا خديجة!'],['صلاح الدين','(ينزل جبينه على يده والجميع يضحك) يوسف! هذه هي القصة! انتظرِ النهاية!'],['مريم','(ضاحكة) ممتاز! إن نجوتَ من جمهورِ بيتِنا… فجمهورُ المسجدِ نزهة!']]},
{h:'م٤ · داخلي — المسجد، لحظة المنبر',d:'السبت. المسجد أكثر امتلاء من المعتاد (انتشر الخبر). صلاح الدين يصعد المنبر الصغير: البسملة… السطر الأول… ثم يحدث المحظور — السطر الثاني يتبخر من رأسه. صمت. ثوانٍ تمر كساعات. عيناه تجدان أباه في الصف الأول يضع يده على قلبه: من قلبك.',dlg:[['صلاح الدين','(يترك الورقة على المنبر… ويرفع رأسه) نسيتُ خطبتي المكتوبة… لكني لن أنسى أبداً يومَ كسرتُ مزهريةَ أمي. (ضحكة دافئة تسري في المسجد… ويبدأ الحكي مرتجلاً: الكرة، الكسر، الاختباء خلف الباب، «الله يراني»، والاعتراف) …يومَها ظننتُ أني سأخسرُ مصروفي. فربحتُ شيئاً أكبر: عرفتُ أن الصدقَ يؤلمُ دقيقةً… والكذبَ يؤلمُ العمرَ كلَّه. قالها نبيُّنا ﷺ: عليكم بالصدق. وأنا أقولُ لكم: جرِّبوهُ عندَ أولِ مزهريةٍ تنكسرُ في بيوتِكم! (يجلس والمسجد بين ضحك وتأثر وتكبير)']],vo:'نسيتُ السطرَ الثاني… فوجدتُ صوتي الحقيقي. يا لها من هديةٍ جاءتْ في ثوبِ كارثة! فتعلمْ يا صاحبي: إذا سقطتْ ورقتُكَ يوماً… فاحكِ حكايتَك. لا أحدَ يملكُ حكايتَكَ غيرُك.'},
{h:'م٥ · داخلي — المسجد، بعد الخطبة',d:'الشيخ إدريس يحتضنه أمام الجميع. رجل عجوز يربت رأسه: «أبكيتَني يا صغير — سأصارحُ ابني الليلةَ بأمرٍ أخفيتُه». أيوب يراقب من بعيد بعينين لامعتين.',dlg:[['الشيخ إدريس','(ممسكاً كتفيه) أتدري ماذا فعلتَ اليوم؟ أصدقُ خطبةٍ سمعَها هذا المنبرُ الصغير… لأنها خرجتْ من هنا (يشير لصدره) لا من هنا (يشير للورقة). احفظْ هذا السرَّ يا صلاح الدين: سيكونُ لكَ مع الكلمةِ شأن… وستقفُ يوماً على منابرَ أكبرَ من هذا بكثير — فلا تنسَ أبداً: القلبُ قبلَ الورقة.'],['صلاح الدين','(يبتسم بحياء) أكبرُ من هذا؟… شيخنا، أنا بالكادِ نجوتُ من دقيقتين!']],vo:'«منابرُ أكبرُ بكثير»… لو عرفَ الشيخُ إدريس يومَها أينَ سأقفُ في آخرِ هذه الحكاية — لكنه في الحقيقة… أظنُّهُ كان يعرف. المربّون الكبارُ يرونَ في الطفلِ ما لا يراهُ الطفلُ في نفسِه.'}],
msg:'احكِ ما عشتَ لا ما حفظت: أصدقُ الكلام ما خرج من القلب — وإذا سقطت ورقتُك فاحكِ حكايتك.',apply:'حضّر كلمة دقيقتين عن قيمة عشتها بنفسك، وألقها على أهلك بعد العشاء — قف معتدلاً وانظر في العيون.'},

{n:39,t:'صندوقُ غزةَ الصغير',ic:'🪙',age:'٩ سنوات ونصف',loc:'المسجد والحي',corner:'ibada',goal:'من الشعور إلى المشروع: أول عمل خيري منظم — الصدقة تدبير لا حماس لحظة',chars:['صلاح الدين','أنس','توم','عمر','الشيخ إدريس','مريم'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، شرارة القرار',d:'صلاح الدين مستلقٍ يقلب حجر أنس في يده، عيناه على رسمة غزة في الجدار. يجلس فجأة ويشعل مصباحه ويبدأ يكتب في دفتر بعنوان كبير: «مشروع».',dlg:[['صلاح الدين','(يكتب ويتمتم) الدعاءُ سلاح… لكن أبي يقول: الدعاءُ مع العملِ سلاحٌ بيدين. أنس قال: يحتاجون دواءً وكهرباء… وأنا عندي: حصالةُ خبرةِ الدراجة، وكعكُ أمي المشهور، وأصدقاء! (يكتب ثلاثة أسماء: عمر — توم — أنس)']],vo:'كلُّ مشاريعِ حياتي الكبرى — التي ستسمعون عنها في هذه الحكاية — بدأتْ من ذلك الدفترِ الصغير، في تلكَ الليلة. الصفحةُ الأولى كانت بعنوان: كيف أساعدُ أطفالَ غزة وأنا في التاسعة؟'},
{h:'م٢ · داخلي — مكتب الشيخ إدريس، فقه المشروع',d:'الفتية الأربعة (صلاح الدين وعمر وأنس وتوم!) أمام الشيخ إدريس، يعرض صلاح الدين خطته من الدفتر: صندوق مزين + بيع كعك بعد الجمعة + عُشر المصروف أسبوعياً.',dlg:[['الشيخ إدريس','(يقلب الدفتر معجباً) خطةٌ ورؤية… لكن ينقصُها ثلاثةُ أعمدةٍ بلا واحدٍ منها ينهارُ أيُّ عملِ خير: أولاً الإذن — أخذتُموهُ الآن مني ومن أهلِكم مساءً. ثانياً الأمانةُ الشفافة: كلُّ قرشٍ يُسجَّلُ في دفترٍ يراهُ من شاء — المالُ العامُّ نارٌ إلا بالحساب. ثالثاً الجهةُ الموثوقة: لا نرسلُ جهدَنا في الهواء — سنرسلُ عبرَ الجمعيةِ المرخصةِ التي يتعاملُ معها المسجد.'],['توم','(رافعاً يده بأدب) سؤال: أنا لستُ مسلماً… هل أستطيعُ المشاركة؟'],['الشيخ إدريس','(يبتسم ابتسامته الواسعة) يا توم… إطعامُ الجائعِ ومساعدةُ المريضِ خيرٌ يجمعُ كلَّ بني آدم. بل أنتَ ضيفُ شرفِ المشروع!']]},
{h:'م٣ · خارجي — ساحة المسجد، مونتاج جُمَع الكعك',d:'مونتاج ثلاث جُمَع: طاولة صغيرة بلافتة رسمها أنس (قبة وبحر وقلب). كعك مريم يباع قطعة قطعة — توم أمهر بائع («جربوا! أنا شاهد محايد على اللذة!»). عمر أمين الصندوق يسجل بدقة. أنس يحكي للمشترين عن غزة بابتسامة لا بدموع. الصندوق يثقل أسبوعاً بعد أسبوع. لقطات صغيرة: عجوز تدس ورقة كبيرة وتوصي «لا تكتبوا اسمي»، طفل يفرغ حصالته كاملة.',dlg:[['رجل مشترٍ','(يمازحهم) كعكةٌ بجنيه؟ غالية!'],['توم','ليست كعكةً يا سيدي… هذه كهرباءُ ليلةٍ لطفلٍ يريدُ أن يقرأ. والطعمُ هدية!'],['الرجل','(يضحك ويدفع خمسة) أعطني إذن خمسَ ليالٍ مضيئة.']]},
{h:'م٤ · داخلي — المسجد، ليلة العد الكبير',d:'بعد شهر: الفتية الأربعة والشيخ حول سجادة عليها الصندوق مفتوحاً — أعمدة عملات مرتبة، وعدّ جماعي بأصوات متداخلة. المبلغ النهائي يكتب على ورقة كبيرة: يفوق توقعهم ثلاث مرات. تحويل رسمي عبر الجمعية — إيصال يعلق في لوحة المسجد للشفافية.',dlg:[['عمر','(يرفع الإيصال) ثلاثةُ أضعافِ ما حلمنا!'],['أنس','(يمسك الإيصال بيدين مرتجفتين وينظر لصلاح الدين) هذا سيصلُ إلى هناك؟… إلى أطفالٍ أعرفُ أسماءَهم ربما… (يبتسم أوسع ابتسامة في السلسلة) شكراً. من جدّتي… شكراً.'],['الشيخ إدريس','احفظوا هذا الشعورَ يا أبنائي — قال ﷺ: اليدُ العليا خيرٌ من اليدِ السفلى. واليومَ… أربعُ أيادٍ صغيرةٍ كانت هي العليا.']],vo:'مبلغُنا كان قطرةً في بحرِ حاجتِهم — كنتُ أعرف. لكنَّ الشيخَ علمني ما أزالَ الحسرة: أنتَ لا تُسألُ عن سدِّ البحر… تُسألُ عن قطرتِك. والقطراتُ يا أصدقائي — حينَ تتعلمُ التنظيمَ — تصيرُ أنهاراً. انتظروا وسترون.'},
{h:'م٥ · داخلي — البيت، درس الاستمرار',d:'صلاح الدين يفرغ حماسه لأمه: «الشهر القادم نجمع ضعفين! ونضيف طاولة ثانية!». مريم تهدئ اندفاعه بحكمتها المعهودة.',dlg:[['مريم','أحسنتم… والآن السؤالُ الذي يفرقُ بين حماسِ شهرٍ وعملِ عمر: ماذا لو تعبتم بعد شهرين؟ الأفضلُ من ضعفين في مرة… نصفٌ يدومُ كلَّ مرة. أحبُّ الأعمالِ إلى اللهِ أدومُها وإن قلّ — القاعدةُ نفسُها: في الحفظِ، وفي الصدقة.'],['صلاح الدين','(يفتح دفتر المشروع ويكتب) القاعدة: جمعةُ كعكٍ واحدةٌ كلَّ شهر — لا نزيدُ في الحماس، ولا نقطعُ في الفتور. (يرفع رأسه) يا ماما… قاعدةُ الجبلِ تعملُ في كلِّ شيء!'],['مريم','(تبتسم) كلُّ شيءٍ عظيمٍ يا حبيبي… جبلٌ يُصعَدُ درجةً درجة.']],vo:'واستمرَّ صندوقُ غزةَ الصغيرُ يعملُ بقاعدةِ الجبلِ سنواتٍ طويلة — حتى بعدَ رحيلي عن مانشستر، بقيَ توم وعمر عليه… لكن تلك قصةٌ لاحقة. المهم: من التاسعةِ تعلمتُ أن الشفقةَ شعور… والرحمةَ مشروع.'}],
msg:'الشفقة شعور والرحمة مشروع: إذن وخطة وشفافية وجهة موثوقة — واليد العليا الدائمة خير من حماس مرة.',apply:'أطلق مشروعك الصغير: خصص علبة للصدقة، ضع فيها جزءاً ثابتاً من مصروفك كل أسبوع، واختر لها هدفاً تحبه.'},

{n:40,t:'رسالةُ الزيتون',ic:'✉️',age:'٩ سنوات ونصف',loc:'بيت العائلة',corner:'parents',goal:'بر الوالدين يمتد للأجداد — ونداء الجذور يبلغ ذروته',chars:['العائلة','ساعي البريد'],
scenes:[
{h:'م١ · خارجي/داخلي — باب البيت، ظهر السبت',d:'جرس الباب. ساعي البريد يسلم ظرفاً سميكاً بطوابع أردنية ملونة وخط عربي مرتجف مألوف. صلاح الدين يستلمه ويقرأ المرسل فيصيح عبر البيت.',dlg:[['صلاح الدين','رسالة! رسالةٌ ورقيةٌ من جدي! (يوسف وشام يتراكضان، ومريم تخرج من المطبخ تمسح يديها)'],['يوسف','ورقية؟! لماذا لم يتصل كالعادة؟'],['أيوب','(يأخذ الظرف ويزنه في كفه بقلق غامض)… جدُّكم من جيلٍ يعرفُ أن بعضَ الكلامِ أثقلُ من أن يُحمَلَ على سلكِ الهاتف. الكلامُ الثقيلُ يُكتَب.']],vo:'في زمنِ الشاشاتِ السريعة، وصلَنا ظرفٌ ورقيٌّ سافرَ أسبوعين. وكان أبي محقاً… فبعضُ الرسائلِ تغيّرُ مصائرَ البيوت.'},
{h:'م٢ · داخلي — مائدة العشاء، قراءة الرسالة',d:'طقس مهيب: الرسالة تُفتح بعد العشاء. من الظرف تسقط ورقة زيتون مجففة — تلتقطها شام الصغيرة. مريم تقرأ بصوتها الدافئ، والكاميرا تتنقل بين الوجوه مع كل فقرة.',dlg:[['مريم','(تقرأ) «بسمِ اللهِ… ولدي أيوب، وقرةَ عيني مريم، وأحفادي الثلاثة: صلاحَ الدين ويوسفَ وشام… إن كانت هذه الرسالةُ تجدُكم بخير، فاعلموا أن كاتبَها بخيرٍ من كلِّ شيءٍ… إلا الشوق. كبرتُ يا أيوب. صارَ صعودُ الدرجِ حكايةً، وصارتِ المواسمُ تمرُّ وأنا أعدُّها عدّاً. البيتُ واسعٌ وأصواتُكم لا تملؤهُ إلا في الشاشة، والزيتونُ أثمرَ هذا العامَ حملاً ما رأيتُ مثلَهُ من سنين… ومدَّ أغصانَهُ يسألُني: أينَ الأحفاد؟»'],['يوسف','(هامساً لأخيه) الشجرُ يسأل؟'],['صلاح الدين','(عيناه على الورقة المجففة، هامساً) اسكتْ… أكملي يا ماما.']]},
{h:'م٣ · داخلي — المائدة، ذروة الرسالة',d:'مريم تصل للفقرة الأخيرة وصوتها يتهدج. أيوب واضع جبهته على يده المشبكة.',dlg:[['مريم','(تقرأ) «…لا آمرُكَ يا ولدي فأنتَ رجلُ بيتِكَ وأدرى بمعاشِك. لكني أقولُها مرةً واحدةً ثم أصمتُ إلى الأبد: الشجرةُ الطيبةُ تثمرُ في كلِّ أرض… لكنها لا تضربُ جذورَها إلا في أرضِها. وصلاحُ الدين — يا أيوب — جذورُهُ تنادي. تعالوا… فالعمرُ يمضي، وعندي له ولإخوتِهِ ما لا يُعلَّمُ في الغربة: أذانٌ يوقظُ لا منبه، وحارةٌ تحفظُ اسمَك، وزيتونةٌ تحتاجُ يداً صغيرةً تسقيها من بعدي. أبوكم: عبدُ القادر».'],['العائلة','(صمت كامل… ورقة الزيتون تدور من يد إلى يد حتى تستقر في كف صلاح الدين)'],['شام','(٢ ونصف، تكسر الصمت بصوتها الطفولي) بابا… لماذا تبكي عينُك؟'],['أيوب','(يمسح عينه ويحملها) لا شيءَ يا شام… جدُّكِ فقط… يكتبُ كما كان أبوهُ يغرس: عميقاً.']]},
{h:'م٤ · داخلي — غرفة صلاح الدين، ليلاً',d:'صلاح الدين لا ينام. ورقة الزيتون أمامه على المكتب تحت ضوء المصباح: يتشممها، يقيسها بإصبعه، يضعها بين صفحات مصحفه بعناية جراح. من النافذة يرى أباه واقفاً وحيداً في الحديقة الخلفية تحت رذاذ خفيف، بلا مظلة، ينظر إلى لا شيء.',dlg:[['صلاح الدين','(يهمس لنفسه عند النافذة) بابا واقفٌ بين بلدين… (ينظر لورقة الزيتون في المصحف ثم لرسمة القبة على الجدار) يا الله… أنا أيضاً لا أعرفُ ماذا أتمنى. هنا مسجدي وأصدقائي ومنبري الصغير… وهناك جدي والزيتونةُ والأذان. اللهم اخترْ لنا… فأنتَ تعلمُ ونحن لا نعلم.']],vo:'تلكَ الليلةَ دعوتُ أولَ دعاءِ استخارةٍ في حياتي — قبلَ أن أتعلمَ صلاتَها. طفلٌ في التاسعةِ يقفُ في نافذةٍ بين وطنين… يسلِّمُ الحيرةَ لمن لا يحتار.'},
{h:'م٥ · داخلي — المطبخ، حوار الفجر الهامس',d:'قبيل الفجر. صلاح الدين نزل ليشرب فسمع والديه في المطبخ — يقف خلف الباب (لا يتجسس… تسمّر). حوار هامس بين أيوب ومريم.',dlg:[['أيوب','(بصوت متعب) …عملي هنا، وبيتُنا، ومدارسُهم، وصندوقُ غزةَ الذي أطلقوه، والناسُ أحبونا… نقتلعُ كلَّ هذا؟'],['مريم','ونتركُ أباكَ يعدُّ المواسمَ وحدَه؟… يا أيوب، أنا أخافُ مما تخاف. لكني أنظرُ لصلاحِ الدين: تاسعةٌ ونصف، وما زالَ قلبُهُ طيناً يتشكل. إن كان سيضربُ جذورَهُ يوماً… فالوقتُ الآن.'],['أيوب','(صمت طويل)… نستخير. ونجمعُهم — البيتُ كلُّهُ يقرر، لا نحن وحدَنا. أطفالُنا ليسوا حقائبَ تُنقَل… شركاءُ يُستشارون.'],['صلاح الدين','(خلف الباب، يبتلع الخبر الهائل ويصعد الدرج على أطراف أصابعه، قلبه يدق)… مجلسُ شورى. قادم.']],vo:'وهكذا زُرعتْ رسالةُ الزيتونِ في تربةِ بيتِنا… وبدأتْ تنبت. الحلقةُ القادمةُ من حياتي كانت على وشكِ أن تبدأ — وكان اسمُها: قرار.'}],
msg:'بعض الرسائل تغير مصائر البيوت: الجذور تنادي — والأجداد كنز لا يعوَّض، فبرّهم قبل أن يعدّوا المواسم وحدهم.',apply:'اسأل والديك الليلة: «ما الشيء الذي تحنّون إليه من بلادكم أو طفولتكم؟» — واستمع للجواب كاملاً بلا مقاطعة.'},

{n:41,t:'مجلسُ الشورى العائلي',ic:'🪑',age:'٩ سنوات ونصف',loc:'غرفة الجلوس',corner:'parents',goal:'الشورى سنة البيوت الكبيرة — والاستخارة قبل القرارات المصيرية',chars:['العائلة كاملة'],
scenes:[
{h:'م١ · داخلي — غرفة الجلوس، افتتاح المجلس',d:'مشهد مهيب مؤثث بعناية: الطاولة المستديرة، أمام كل فرد ورقة وقلم — حتى أمام يوسف (٥) وشام (٢ ونصف، ورقتها للشخبطة). أيوب يفتتح بجدية اجتماع رسمي.',dlg:[['أيوب','بسمِ الله… هذا أولُ مجلسِ شورى كاملٍ في تاريخِ عائلتِنا، وموضوعُهُ أكبرُ قرارٍ منذ وُلدتم: هل ننتقلُ للعيشِ في عمّان قربَ جدِّكم؟ وقبلَ أن نبدأ — ثلاثةُ قوانين: كلُّ صوتٍ هنا محترمٌ مهما صغُرَ صاحبُه. ومن يتكلمُ لا يُقاطَع. والصراحةُ عبادة — قولوا ما تشعرون لا ما نحبُّ أن نسمع.'],['يوسف','(رافعاً يده فوراً) سؤالُ نظام: هل في عمّان مثلجات؟'],['أيوب','(بجدية كاملة دون ضحك) سؤالٌ وجيهٌ يُسجَّل: نعم، وأطعمُ مما هنا. تفضلْ سجِّلْها في ورقتِك.']],vo:'قد تضحكون من سؤالِ يوسف… لكن أبي لم يضحك. كان يعلِّمُنا في تلكَ الجلسةِ درساً يفوقُ قرارَ الهجرةِ نفسَه: أن الإنسانَ — مهما صغُر — يستحقُّ أن يُسمَع. من ذلك المجلسِ خرجتْ كلُّ مجالسِ الشورى في حياتي… حتى تلك التي ستضمُّ يوماً ممثلي أربعين بلداً.'},
{h:'م٢ · داخلي — المجلس، العرض الأمين',d:'أيوب يقسم السبورة الصغيرة (سبورة مكتب صلاح الدين استعيرت للمناسبة) عمودين: نكسب / نخسر — ويملؤها بصراحة نادرة.',dlg:[['أيوب','لنكن أمناء — نخسر: عملي ومرتبي المستقر، مدرستَكم ومعلمتَكم كلارك، النادي، توم وعمر وأنس، مسجدَ النورِ والشيخَ إدريس، وبيتاً عشنا فيه عشرَ سنين. ونكسب: جدَّكم وجدتَكم — والعمرُ لا يشترى، لغةَ القرآنِ من أهلِها، أذاناً في كلِّ حي، أقاربَ وحارةً تعرفُنا، وقرباً من… (ينظر لصلاح الدين) القدس. ثمنُ التذاكرِ الحقيقي يا أولادي ليس مالاً — إنه فراقُ أحبةٍ هنا للقاءِ أحبةٍ هناك. لا يوجدُ خيارٌ بلا وجع… يوجدُ خيارٌ يستحقُّ وجعَه.']]},
{h:'م٣ · داخلي — المجلس، أصوات الصغار',d:'جولة الأصوات: يوسف متحمس ببساطة الخامسة («جدي يحملُني على كتفيه في الشاشة — أريدُ الكتفَ الحقيقي!»). مريم تتكلم عن أم تريد لأولادها الجذور. ثم يصل الدور لصلاح الدين — الجميع يعرف أن صوته الأثقل. يقف وبيده ورقته وقد كتب فيها عمودين مثل أبيه.',dlg:[['صلاح الدين','كتبتُ مثلَك يا بابا… وبكيتُ وأنا أكتبُ الجهةَ اليسرى: توم أخي وإن لم يكن أخي. والمنبرُ الصغيرُ الذي نسيتُ عليه سطري. وصندوقُ غزةَ من سيديرُه؟… (يرفع رأسه) لكني كتبتُ في الجهةِ اليمنى شيئاً واحداً أثقلَ من كلِّ اليسار: جدي قال «صلاحُ الدين جذورُهُ تنادي». وأنا… أنا سمعتُ النداءَ يا بابا. من يومِ رأيتُ المفتاحَ في الشاشة. أصوِّتُ: نذهب. بشرطين!'],['أيوب','(يرفع حاجبيه) شروط؟ تفضل يا سيد.'],['صلاح الدين','الأول: نودِّعُ الجميعَ وداعاً يليقُ — لا نختفي كالغرباء. والثاني: صندوقُ غزةَ يستمرُّ — أسلِّمُهُ لتوم وعمر قبلَ أن نسافر، بالدفترِ والقواعد.'],['مريم','(تهمس لأيوب ودموعها تلمع) اسمعْهُ… يفاوضُ كالكبارِ على الوفاء.']]},
{h:'م٤ · داخلي — المجلس، درس الاستخارة',d:'أيوب يلخص: الأصوات تميل للرحيل والقلوب خائفة. يرفع يده معلناً الخطوة الأخيرة.',dlg:[['أيوب','الشورى قالت كلمتَها… بقيَ صوتٌ أخير — أهمُّ الأصوات. نبيُّنا ﷺ علَّمَنا إذا همَّ أحدُنا بالأمرِ أن يركعَ ركعتين ثم يقولَ دعاءَ الاستخارة: اللهمَّ إني أستخيرُكَ بعلمِك، وأستقدرُكَ بقدرتِك… فأنتَ تعلمُ ولا أعلم. الليلةَ كلُّ من يصلي في هذا البيتِ يستخير. والاستخارةُ يا أولادي ليست حلماً نراهُ في المنام — إنها تفويضٌ: نعملُ بما ترجَّح، وقلوبُنا مطمئنةٌ أن اللهَ لن يختارَ لعبدٍ فوَّضَهُ إلا الخير.'],['صلاح الدين','وإن ذهبنا ثم صعُبتِ الأمور؟ هل يعني أن الاستخارةَ خابت؟'],['أيوب','(يضع يده على رأسه) سؤالُ العارفين! لا يا بني… الخيرُ الذي يختارُهُ اللهُ قد يمرُّ بصعوبة، كالدواءِ المر. علامةُ الاستخارةِ ليست طريقاً بلا حجارة… بل قلباً لا يندم.']],vo:'قلبٌ لا يندم… احفظوها. فبعدَ سنواتٍ من تلكَ الليلة، حينَ اشتدَّتْ عليَّ غربةُ اللغةِ في عمّان وأنا أبكي تحتَ لحافي — كانت هذه الجملةُ حبلَ نجاتي: نحن ما ندمنا… نحن نتسلقُ الجبل.'},
{h:'م٥ · داخلي — البيت، مشهد الاستخارة الليلي',d:'مشهد ختامي بصري بديع بلا حوار تقريباً: البيت مطفأ الأنوار إلا مصابيح خافتة. لقطات متوازية: أيوب يصلي في غرفة الجلوس… مريم على سجادتها في الغرفة… صلاح الدين على سجادته الخضراء الصغيرة يقرأ الدعاء من ورقة كتبها له أبوه، يتهجى كلماته العظيمة. يوسف نائم معانقاً ورقته التي كتب فيها «مثلجات + كتف جدي». الكاميرا تخرج من نافذة البيت: بيت إنجليزي صغير مضاء بثلاث صلوات في ليل مانشستر.',dlg:[['صلاح الدين','(آخر همسة، على سجادته) …فإن كنتَ تعلمُ أن هذا الأمرَ خيرٌ لي في ديني ومعاشي وعاقبةِ أمري… فاقدُرْهُ لي ويسِّرْهُ لي ثم باركْ لي فيه. (يرفع رأسه) وبارك لجدي… ولتوم… وللزيتونة.']],vo:'وفي صباحِ اليومِ الثالث، وجدنا أبي يبتسمُ ابتسامةً لم نرَها من أسابيع، ويقول: القلبُ اطمأن… نتوكل. احجزوا التذاكر: نسافرُ يومَ يتمُّ صلاحُ الدين عاشرتَه. وهكذا يا أصدقائي… تُتَّخذُ القراراتُ الكبرى في البيوتِ المسلمة: شورى تجمعُ العقول… واستخارةٌ تطمئنُ القلوب.'}],
msg:'هكذا تقرر البيوت الكبيرة: شورى يُسمع فيها أصغر صوت، واستخارة تفوّض أحكم العالمين — فيخرج القرار وقلوبٌ لا تندم.',apply:'اقترح على أهلك «مجلس شورى» لقراركم القادم (رحلة، شراء، برنامج) — وتعلّم دعاء الاستخارة فهو سلاح العمر.'},

{n:42,t:'هديةُ الوداع',ic:'🎁',age:'١٠ سنوات إلا شهراً',loc:'مانشستر — جولة الوداعات',corner:'social',goal:'الوفاء عند الفراق: نودّع الناس بالإحسان ونترك أثراً باقياً',chars:['صلاح الدين','توم','عمر','أنس','بيلي','داني','الشيخ إدريس','المدرب هاريس','المعلمة كلارك'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، قائمة الوداع',d:'على المكتب ورقة بعنوان «قائمة الوداع — لا أحد يُنسى»: أسماء وسهم أمام كل اسم يشير لهديته أو وداعه. صلاح الدين يراجعها كقائد عمليات.',dlg:[['مريم','(تطل من الباب) شهرٌ على السفر وأنتَ تخطط كأنها معركة!'],['صلاح الدين','هي كذلك يا ماما — معركةُ وفاء! أبي قال: الناسُ تُقاسُ بخواتيمِها. عشرُ سنينَ من الحبِّ لا تُغلَقُ برسالةِ «مع السلامة» — تُغلَقُ باباً باباً… وبيدين مليئتين.']],vo:'علَّمَتني قائمةُ الوداعِ تلك أن الوفاءَ ليس شعوراً يفيض… بل عملاً يُنظَّم. الفرحُ نُنظِّمُهُ أعراساً — فلماذا نتركُ الوداعَ للفوضى؟'},
{h:'م٢ · داخلي/خارجي — مونتاج الوداعات الأربعة',d:'مونتاج مؤثر: (١) المدرسة — يهدي المعلمة كلارك مجسم دورة الماء نسخة مصغرة صنعها بيده، فتضعه على مكتبها: «سيشرح بعدك لكل صف». بيلي يعانقه طويلاً: «أنت أول من رآني صديقاً لا مشكلة». داني الضخم يمسح عينيه بقبضته غاضباً من دموعه. (٢) النادي — يسلم المدرب هاريس ميداليته الأولى (الورقية! «المؤمن القوي») فيعلقها هاريس في خزانة الكؤوس الزجاجية بين الذهب: «أغلى ما في الخزانة — قصتها أثقل من معدنها». (٣) عمر وأنس — يسلمهما دفتر صندوق غزة رسمياً: توقيع وتسليم عهدة كاملة أمام الشيخ إدريس. (٤) ساعته الرياضية يهديها لعمر: «وقِّت بها فوزكم القادم».',dlg:[['أنس','(ممسكاً الدفتر) تعدُنا أن تراسلَنا؟'],['صلاح الدين','أعدُكم بأفضل: سأراسلُكم من مكانٍ أقربَ إلى بيتِ جدتِكَ يا أنس… وسأرى فلسطينَ من جبلٍ هناك — سأنظرُ عنكَ أنتَ أيضاً.']]},
{h:'م٣ · داخلي — مسجد النور، كلمة المنبر الأخيرة',d:'جمعة الوداع. المسجد ممتلئ — انتشر خبر سفر العائلة. الشيخ إدريس يدعو صلاح الدين لمنبر الناشئة كلمة أخيرة. يصعد بلا ورقة هذه المرة.',dlg:[['صلاح الدين','قبل خمسِ سنين، دخلتُ هذا المسجدَ أولَ مرةٍ ممسكاً يدَ أبي، فأعطاني الشيخُ تمرةً وقال: المسجدُ بيتُك. لم أفهمْها يومَها… أفهمُها الآن وأنا أودِّع: هذا المسجدُ علَّمَني أن للغريبِ وطناً اسمُهُ السجادة. هنا صليتُ أولَ جمعة، وحفظتُ أولَ جزء، وخطبتُ أولَ خطبةٍ ونسيتُ نصفَها… (ضحك ودموع في المسجد) سأحملُكم معي حيثُ أذهب. وأترك لكم صندوقَ غزةَ أمانةً — أطعموهُ كلَّ جمعة، فإن جعتُم للأجرِ فتذكروا: فيهِ يدُ توم أيضاً — فليكن صندوقَنا جميعاً. السلامُ عليكم… يا أهلي الأولين.'],['الشيخ إدريس','(يحتضنه والمسجد يموج بالتكبير والدعاء، يهمس في أذنه) اذهبْ يا صلاحَ الدين… بعضُ الشجرِ يُنقَلُ صغيراً ليعانقَ الشمس. وسنبقى نحن جذرَكَ الإنجليزي — لا تنسَنا إذا أثمرت.']]},
{h:'م٤ · خارجي — حديقة البيتين، وداع توم',d:'الوداع الأصعب تُرك للنهاية. الصديقان على السور الفاصل بين الحديقتين — مجلسهما الأزلي. صلاح الدين يخرج هديتين: مصحفاً مترجماً بالإنجليزية فاخر التجليد، وظرفاً.',dlg:[['صلاح الدين','هذا الكتابُ الذي تسألُني عنه من يومِ سألتَني «من هو الله» — كلامُ ربي مترجماً لك. لا أستعجلُك… اقرأهُ كما تقرأ رسائلَ صديق. وهذا عنواني الجديدُ وعهدٌ مكتوبٌ بخطي: رسالةٌ كلَّ شهرٍ — أنا أكتبُ الأولى.'],['توم','(يمسك المصحف بيدين ويقلبه… ثم يرفع عينين حمراوين) أنتَ أولُ من قالَ لي «الجارُ له حق»… فمن سيكونُ جاري الآن؟ (يخرج هو هديته: صورة مؤطرة لهما صغيرين يبنيان برج المكعبات يوم صحن الكعك الأول) أمي وجدتْها. قالت: أعطِها له… وقل لأمِّهِ إن صحنَ الكعكِ ذاك… ما زالَ أطيبَ ما دخلَ بيتَنا.'],['صلاح الدين','(يحتضن الصورة ويبتلع دموعه)… سأعلقُها فوقَ مكتبي في عمّان. يا توم… الجيرةُ ليست جداراً مشتركاً. الجيرةُ عهد. ونحن جاران… ولو بيننا بحر.']],vo:'رسالةٌ كلَّ شهر… حافظنا عليها إحدى عشرةَ سنة. وقد عرفتم من حلقةٍ سابقةٍ ماذا فعلَ اللهُ بتلكَ الرسائل. فيا من تودِّعُ صديقاً اليوم: الوداعُ الحقُّ ليس نهايةَ الحكاية… بل نقلُها إلى ورقٍ أطولَ نفَساً.'},
{h:'م٥ · داخلي — البيت الفارغ، اللقطة الأخيرة',d:'البيت مفرغ إلا من الصناديق. العائلة الجديدة (عائلة مسلمة صومالية) تستلم المفاتيح. صلاح الدين يقود أطفالهم الثلاثة في جولة: «هذا الحائط لجبل الحفظ… وهذه الزاوية أفضل ركن صلاة — الشمس تدخلها في العصر». وعلى جدار الصالون تُترك لوحة «الله» الخطية معلقة مكانها.',dlg:[['الأم الصومالية','لوحتُكم الجميلة… نسيتموها!'],['مريم','ما نسيناها… ورَّثناها. هذا البيتُ تعلَّمَ يذكرُ الله عشرَ سنين — أحببنا أن يبقى له لسانُ ذكر. (تبتسم) البيوتُ يا أختي كالقلوب… تحتاجُ من يبقيها عامرة.']],vo:'وأغلقنا البابَ الأخضرَ للمرةِ الأخيرة. عشرُ سنينَ في ظرفِ ساعة… لكننا خرجنا محمَّلين لا خاويين: بحبِّ مسجدٍ، ووفاءِ أصدقاء، ولوحةٍ بقيتْ تذكرُ اللهَ خلفَنا. اتركوا أثراً في كلِّ مكانٍ تغادرونه يا أصدقائي… فالأثرُ الطيبُ وطنٌ ثانٍ.'}],
msg:'الناس تُقاس بخواتيمها: نظّم وداعك كما تنظم أفراحك — اشكر وأهدِ وسلّم الأمانات واترك أثراً يذكر الله بعدك.',apply:'تعلم فن الوداع: إن غادرت صفاً أو نادياً أو جيراناً فلا تنسحب بصمت — اشكر وأهدِ واترك أثراً طيباً يذكرك.'},

{n:43,t:'ماذا نضعُ في الحقيبة؟',ic:'🧳',age:'١٠ سنوات إلا أياماً',loc:'غرفة صلاح الدين — ليلة السفر',corner:'heart',goal:'الزهد ميزان: الأشياء تخدم القلب لا تملؤه — ماذا يستحق أن يُحمَل؟',chars:['صلاح الدين','مريم','أيوب','يوسف'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، فوضى الاختيار',d:'الغرفة ساحة معركة: عشر سنين من الأشياء مبعثرة — ألعاب، كتب، ميداليات، مجسمات، رسومات. في الوسط حقيبة واحدة مفتوحة فارغة. صلاح الدين يقف حائراً وقد كدس بجانبها جبلاً يفوق حجمها عشر مرات.',dlg:[['صلاح الدين','(يصيح نحو الباب) ماما! مستحيل! كلُّ شيءٍ هنا مهم! الديناصورُ هديةُ توم، والسفينةُ اشتريتُها بمالي، وهذه أولُ ورقةٍ كتبتُ عليها الألِف، و…'],['مريم','(تدخل وتجلس على الأرض وسط الفوضى بهدوء تام) كلُّها قصص… أعرف. والآن اسمع قاعدةَ الحقيبةِ الوحيدة — قاعدةً ستنفعُكَ في كلِّ أسفارِ عمرِك: احملْ ما يحملُك… ولا تحملْ ما يُثقلُك.'],['صلاح الدين','وكيف أعرفُ الفرق؟'],['مريم','اسألْ كلَّ شيءٍ سؤالاً واحداً: هل تخدمُ قلبي هناك… أم مجردُ ذكرى تسكنُ رفاً؟ الذكرياتُ يا حبيبي لا تُحمَلُ في الحقائب — تُحمَلُ هنا (تشير لصدره)… والحقيبةُ للسلاح.']],vo:'احملْ ما يحملُك… سافرتُ بعدَها في حياتي مئةَ سفرة — إلى مؤتمراتٍ وقوافلَ وعواصمَ — وما خنتُ قاعدةَ أمي مرة: حقيبةٌ صغيرةٌ… وقلبٌ مليء.'},
{h:'م٢ · داخلي — الغرفة، قرار التوزيع',d:'صلاح الدين ينظر لجبل الألعاب طويلاً… ثم يبدأ بحركة مفاجئة: يجمعها في أكياس كبيرة ويكتب على كل كيس وجهته.',dlg:[['صلاح الدين','قررت! الألعابُ لا تخدمُ قلبي… لكنها ستخدمُ قلوباً غيري: كيسٌ لأطفالِ المسجد، وكيسٌ لأطفالِ العائلةِ الجديدةِ في بيتِنا، والديناصورُ الكبيرُ لأخي يوسف — (يلتفت ليوسف المتلصص من الباب) بشرطِ أن تعيرَهُ شام حين تكبر!'],['يوسف','(يحتضن الديناصور بذهول) لي؟! أغلى ديناصوراتِك؟!… إذن خذْ أنتَ سيارتي الحمراء! (يركض ويعود بها لاهثاً)'],['صلاح الدين','(يضحك ويرفض بلطف) احتفظْ بها يا بطل… لكن انظرْ ماذا تعلمتَ الآن: العطاءُ معدٍ! أعطيتُكَ فأردتَ العطاء — هكذا يدورُ الخير.']],vo:'اكتشفتُ تلكَ الليلةَ سرَّ التخفف: أثقلُ طريقةٍ للاحتفاظِ بأشيائكَ أن تكدسَها… وأخفُّها أن تهديَها. الهديةُ تحفظُ الشيءَ في قلبين.'},
{h:'م٣ · داخلي — الغرفة، الخمسة المختارة',d:'المشهد المحوري: الحقيبة شبه جاهزة بالملابس. صلاح الدين يصف على السرير «كنوز القلب» ويقدمها للكاميرا واحدة واحدة (يكسر الجدار الرابع بلطف — أسلوب توثيقي دافئ).',dlg:[['صلاح الدين','(يحمل كل قطعة بيدين) واحد: مصحفي الأولُ الصغير — فيه ورقةُ زيتونِ جدي بين سورةِ الفيلِ وقريش. اثنان: رسمةُ القبةِ الذهبية — أولُ قدسٍ عرفتُها. ثلاثة: بطاقةُ «اللهُ يراني» بخطِّ أمي — درعي السري. أربعة: حجرُ أنس — فيه بحرُ غزةَ كلُّه. خمسة: صورةُ توم — يومَ كنا نبني برجاً ونحسبُهُ أعلى بناءٍ في العالم. (يضعها في الجيب الأمامي ويغلق السحاب) انتهى… عشرُ سنينَ في جيبٍ أمامي.']]},
{h:'م٤ · داخلي — عتبة الغرفة، نظرة الأب',d:'أيوب كان واقفاً عند الباب يراقب صامتاً طوال المشهد. يدخل ويرفع الحقيبة بيد واحدة مندهشاً من خفتها، ثم يجلس ويخرج دفتره الجلدي الصغير (دفتر خواطره الذي ظهر لمحات في حلقات سابقة) ويكتب أمام ابنه.',dlg:[['صلاح الدين','ماذا تكتبُ يا بابا؟'],['أيوب','(يقرأ ما كتب بصوت هادئ) «الليلة… وزنتُ حقيبةَ ابني فوجدتُها خفيفة، ووزنتُ اختياراتِهِ فوجدتُها من ذهب: كتابُ ربِّه، وقبلةُ أمتِه، ومراقبةُ خالقِه، وقضيةُ إخوتِه، ووفاءُ صديقِه. اللهم إني أشهدُكَ أني راضٍ عنه… فارضَ عنه». (يغلق الدفتر ويقبل رأس ابنه بلا كلمة أخرى)'],['صلاح الدين','(بعينين دامعتين، هامساً)… هذه أثقلُ هديةِ سفرٍ يا بابا. اكتبْها لي يوماً في ورقة.'],['أيوب','ستجدُها في الدفترِ كلِّه… يومَ يصيرُ الدفترُ لك.']],vo:'«يومَ يصيرُ الدفترُ لك»… مرَّتِ الجملةُ يومَها عابرة. وبعدَ سنينَ طويلة، في يومٍ حزينٍ جداً وجميلٍ جداً، فهمتُها. لكن رويداً… ما زلنا في ليلةِ الحقيبة.'},
{h:'م٥ · داخلي — الغرفة الفارغة، اللقطة الأخيرة',d:'الغرفة أصبحت شبه فارغة: سرير مجرد، وجدران عليها مستطيلات باهتة مكان الرسومات المنزوعة. صلاح الدين يقف في المنتصف يلقي نظرة الوداع. يقترب من الجدار حيث كانت رسمة القبة — يضع كفه على المستطيل الباهت.',dlg:[['صلاح الدين','(هامساً للغرفة) شكراً… هنا حلمتُ بالأبواب، وهنا حفظتُ الجبل، وهنا اعترفتُ بالمزهرية. (يبتسم) الغرفةُ القادمةُ أقربُ إلى الأبوابِ بثلاثةِ آلافِ ميل… (يطفئ النور للمرة الأخيرة) تصبحين على خير.']],vo:'وهكذا تُطوى الفصول: بحقيبةٍ خفيفة، وقلبٍ مثقلٍ بالحب، وكفٍّ على جدارٍ باهت. غداً… الطائرة. غداً أتمُّ عاشرتي فوقَ الغيوم. غداً يبدأ النصفُ الثاني من الحكاية.'}],
msg:'احمل ما يحملك ولا تحمل ما يثقلك: الذكريات تسكن القلب لا الحقائب — وأخف طريقة للاحتفاظ بأشيائك أن تهديها.',apply:'العب لعبة الحقيبة: لو سافرت غداً بحقيبة واحدة، ما خمسة أشياء تحملها؟ اكتبها — وتصدق بلعبة واحدة تحبها اليوم.'},

{n:44,t:'فوقَ الغيوم',ic:'✈️',age:'عيد ميلاده العاشر',loc:'مطار مانشستر — الطائرة',corner:'ibada',goal:'دعاء السفر وفقه الرحيل: الأرض لله والمؤمن مسافر دائم — نهاية الفصل الأول',chars:['العائلة','توم','الشيخ إدريس'],
scenes:[
{h:'م١ · داخلي — مطار مانشستر، فجراً',d:'صالة مغادرة شبه خالية، حقائب مصفوفة، شام نائمة على كتف أمها ويوسف يجر حقيبته الصغيرة نصف نائم. وعند بوابة الدخول — مفاجأة: قامة الشيخ إدريس الطويلة، وبجانبه توم وأمه، جاؤوا في الخامسة فجراً.',dlg:[['أيوب','(مذهولاً) شيخنا! في هذا الفجر؟!'],['الشيخ إدريس','(يضحك ضحكته العميقة) رجلٌ يشهدُ فجرَ المسجدِ كلَّ يوم… أيفوتُهُ فجرُ وداعِ الأحباب؟ جئنا نطبقُ السنة: زوِّدوا المسافرَ بالدعاء. (يضع يده على رأس صلاح الدين) أستودعُ اللهَ دينَكَ وأمانتَكَ وخواتيمَ عملِك.'],['توم','(يمد لصلاح الدين كيساً ورقياً صغيراً) لا تفتحْهُ إلا فوقَ الغيوم. عهدٌ؟'],['صلاح الدين','(يبتلع الغصة ويمسك الكيس) عهدُ جيران.']],vo:'عيدُ ميلادي العاشر… لا كعكةَ ولا بالونات. بدلاً منها: مطارٌ فجريٌّ، ودعاءُ شيخٍ، وكيسٌ ورقيٌّ ممنوعٌ من الفتحِ حتى الغيوم. وأقسمُ لكم… ما تمنيتُ عيداً غيرَه.'},
{h:'م٢ · داخلي — الطائرة، درس المدرج',d:'العائلة في مقاعدها، صلاح الدين عند النافذة. المحركات تزأر — يوسف يمسك ذراع أبيه بذعر. أيوب يحول اللحظة درساً.',dlg:[['أيوب','(بصوت مسموع للأولاد) أتعرفون ماذا نقولُ الآن؟ نبيُّنا ﷺ ما ركبَ ظهرَ سفرٍ إلا قالَها. رددوا معي: سبحانَ الذي سخَّرَ لنا هذا وما كنا له مقرنين، وإنا إلى ربنا لمنقلبون.'],['صلاح الدين','(يردد ثم يسأل فوق صوت المحركات) ما معنى «ما كنا له مقرنين»؟'],['أيوب','يعني: ما كنا نقدرُ على ترويضِهِ لولا الله! انظرْ حولك: مئتا طنٍّ من الحديدِ ستطيرُ الآن كالريشة — من علَّمَ الإنسانَ هذا؟ الذي خلقَ له العقل! نركبُ العجائبَ ونشكرُ صانعَ العقولِ التي صنعتْها.'],['يوسف','(مسترخياً فجأة) إذن الطيارةُ… سجّادةُ الريحِ الحقيقية!'],['الطائرة','(تقلع — وجه صلاح الدين ملتصق بالنافذة: مانشستر تصغر… البيوت نقاط… المدينة كلها غيمة رمادية جميلة)']]},
{h:'م٣ · داخلي — الطائرة، هدية الارتفاع',d:'فوق الغيوم — بحر أبيض مضيء تحت شمس صافية. مريم تخرج من حقيبتها اليدوية علبة ملفوفة بشريط أخضر.',dlg:[['مريم','عيدٌ سعيدٌ يا ابنَ العاشرة… ظننتَ أننا نسينا؟'],['صلاح الدين','(يفتحها: مصحف أزرق فاخر متوسط الحجم، على غلافه حفرٌ ذهبي: «مصحفُ صلاحِ الدين — المرحلةُ الثانية») مصحفٌ جديد!… لماذا «المرحلةُ الثانية»؟'],['مريم','لأن مصحفَكَ الأولَ الصغيرَ حفظتَ فيه وأنتَ طفلُ مانشستر… وهذا ستحفظُ فيه — إن شاء الله — بقيةَ كتابِ اللهِ وأنتَ فتى عمّان. لكلِّ مرحلةٍ مصحفُها… ولكلِّ مصحفٍ حكايتُه. افتحِ الصفحةَ الأولى.'],['صلاح الدين','(يقرأ إهداءً بخط أمه) «إلى من سيحملُ النورَ من مدينةِ الضبابِ إلى مدينةِ الشمس: أكملِ الجبل». (يحتضن المصحف ويغمض عينيه)']],vo:'ثم تذكرتُ كيسَ توم — نحن فوقَ الغيوم، والعهدُ حانَ وقتُه. فتحتُه: بوصلةٌ نحاسيةٌ قديمةٌ من مقتنياتِ جدِّهِ البحّار… وورقةٌ بخطِّه: «لكي لا تضيعَ أبداً — وجِّهْها نحونا أحياناً. جارُكَ توم». رفعتُ البوصلةَ نحوَ النافذة… وضحكتُ من قلبي: توم يا توم… سأوجهُها نحوَ شيءٍ أبعد. لكنكَ ستكونُ دائماً على الطريق.'},
{h:'م٤ · داخلي — الطائرة، ساعة التأمل',d:'العائلة تغفو واحداً بعد الآخر. صلاح الدين وحده مستيقظ عند النافذة: تحته تنزاح الغيوم عن أوروبا — أنهار كخيوط فضية، جبال، ثم بحر يلمع. يخرج كنوزه الخمسة من الجيب الأمامي ويصفها على الطاولة الصغيرة: المصحف الأول، الرسمة، البطاقة، الحجر، الصورة — ويضيف إليها البوصلة والمصحف الأزرق. سبعة.',dlg:[['صلاح الدين','(يهمس وهو يرتبها) الفصلُ الأول: خمسةُ كنوز… الفصلُ الثاني يبدأ بسبعة. (ينظر من النافذة للأرض البعيدة) كلُّ هذه البلادِ لله… يا الله، كم أرضُكَ واسعة! جدي محقٌّ: نحن لا نسافر… نحن ننتقلُ من غرفةٍ إلى غرفةٍ في بيتِك.']],vo:'ومن يومِها أحملُ في قلبي فقهَ الطائرات: المؤمنُ مسافرٌ دائم — والأرضُ كلُّها للهِ مساجدُ وطرق. من فهمَها لم يخفِ الرحيل… ومن خافَ الرحيلَ لم يعرفْها بعد.'},
{h:'م٥ · داخلي/خارجي — هبوط عمّان، اللقطة الختامية للمرحلة',d:'إعلان الهبوط. الغيوم تنشق عن جبال عمّان الذهبية في ضوء الغروب — تباين ساحر مع رمادية الإقلاع. الطائرة تنخفض… تلامس الأرض. صلاح الدين يضغط بطاقة أمه في كفه: «بسم الله». عبر النافذة في صالة الوصول: قامة منحنية بكوفية بيضاء تلوح بعصاها بفرح طفولي — الجد عبد القادر، وبجانبه الجدة خديجة تبكي وتضحك معاً وترفع صينية كعك ملفوفة.',dlg:[['يوسف','(يصرخ ويلصق وجهه بالزجاج) الكتف! أرى الكتفَ الحقيقي!!'],['صلاح الدين','(يهمس وعيناه على جده خلف الزجاج… يرفع يده ويلوح ببطء)… وصلنا يا جدي. جذوري جاءتْ إلى أرضِها.']],vo:'انتهى الفصلُ البريطاني: عشرُ سنينَ صنعتْ مني بذرةً صالحة. وبدأ فصلُ الأرض: عشرٌ أخرى ستصنعُ منها — بإذن الله — شجرة. أما الثمرة… فلها فصلٌ ثالث. اقلبوا الصفحةَ معي: عمّان تنادي.'}],
msg:'سبحان الذي سخر لنا هذا: المؤمن مسافر دائم والأرض كلها لله — من فهمها لم يخف رحيلاً ولا بداية جديدة.',apply:'احفظ دعاء السفر: «سبحان الذي سخر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون» — وقله في أول ركوب قادم.'}
]});
